1	import { isNavigable, type Dock, type ShipTuning } from "@pirate-sea-race/content";
2	import type { SimulationConfig } from "./config.js";
3	import { divTrunc } from "./fixed.js";
4	import { HEADING_DX, HEADING_DY, HEADING_SCALE, normalizeHeading } from "./heading.js";
5	import { AXIS_SCALE, INTERACT_BUTTON, sanitizeInput, type PlayerInput } from "./input.js";
6	import { NOT_DOCKED, tileCentre, WORLD_STEP_INTERVAL, type MatchState, type ShipState } from "./state.js";
7	
8	/**
9	 * Held inputs by ship id. A ship without an entry sails as neutral input, except that a moored ship keeps the throttle
10	 * it moored with (`mooredThrottle`): a missing entry is no input at all (the server leaves it out when a player's input
11	 * lapsed), so it cannot release that throttle, and the player's unchanged held keys do not cast off when they resume.
12	 */
13	export type StepInputs = Readonly<Record<string, PlayerInput>>;
14	
15	export function isWorldStep(frame: number): boolean {
16	  return frame % WORLD_STEP_INTERVAL === 0;
17	}
18	
19	/**
20	 * Advances the match clock by one 60 Hz step and returns the new state. World logic (sailing) runs only when the new
21	 * frame is a multiple of WORLD_STEP_INTERVAL. The input state is never mutated.
22	 */
23	export function step(config: SimulationConfig, state: MatchState, inputs: StepInputs): MatchState {
24	  const frame = state.frame + 1;
25	  if (!isWorldStep(frame)) return { ...state, frame };
26	  return {
27	    ...state,
28	    frame,
29	    worldTick: state.worldTick + 1,
30	    ships: state.ships.map((ship) => {
31	      const input = inputs[ship.id];
32	      return input === undefined && ship.dock !== NOT_DOCKED ? ship : sail(config, ship, sanitizeInput(input));
33	    }),
34	  };
35	}
36	
37	/**
38	 * One world step of one ship (§3). The throttle (`-moveY`) accelerates, brakes or reverses; `moveX` turns the
39	 * heading; the ship then moves along its heading and stops or slides against land, shoals and the map edge.
40	 *
41	 * Docking: interact near a dock moors the ship there (at the dock tile's centre, speed 0) at any speed, when its hull
42	 * is on or beside the berth tile or could sail straight there from within reach (`dockInReach`). Neither speed nor
43	 * throttle matters, so a ship driven at its dock with ahead and interact held moors on the first step it starts beside
44	 * the berth or within reach, from any angle. A moored ship stays put while interact is held,
45	 * without throttle, or while the throttle it moored with is still held; releasing that throttle and then any throttle
46	 * (or the other direction) casts off and sails in the same step.
47	 */
48	export function sail(config: SimulationConfig, ship: ShipState, input: PlayerInput): ShipState {
49	  const tuning = config.ship;
50	  const throttle = -input.moveY;
51	  const interact = (input.buttons & INTERACT_BUTTON) !== 0;
52	  const direction = Math.sign(throttle);
53	  let dock = ship.dock;
54	  if (dock !== NOT_DOCKED) {
55	    if (direction === 0 || interact || direction === ship.mooredThrottle) {
56	      const mooredThrottle = direction === 0 ? 0 : ship.mooredThrottle;
57	      return ship.speed === 0 && ship.mooredThrottle === mooredThrottle ? ship : { ...ship, speed: 0, mooredThrottle };
58	    }
59	    dock = NOT_DOCKED;
60	  } else if (interact) {
61	    const berth = dockInReach(config, ship.x, ship.y);
62	    if (berth !== undefined) {
63	      return { ...ship, ...tileCentre(config, berth.tileX, berth.tileY), speed: 0, dock: berth.id, mooredThrottle: direction };
64	    }
65	  }
66	
67	  const heading = normalizeHeading(ship.heading + Math.sign(input.moveX) * tuning.turnRate);
68	  const speed = nextSpeed(tuning, ship.speed, throttle);
69	  const dx = divTrunc(speed * HEADING_DX[heading]!, HEADING_SCALE);
70	  const dy = divTrunc(speed * HEADING_DY[heading]!, HEADING_SCALE);
71	  const x = sweepX(config, ship.x, ship.y, dx);
72	  const y = sweepY(config, x, ship.y, dy);
73	  // Blocked on every axis it tried to move along: the ship has run aground and stops. Blocked on one axis only, it
74	  // slides along the obstacle on the other.
75	  const aground = (dx !== 0 || dy !== 0) && x === ship.x && y === ship.y;
76	  return { ...ship, x, y, heading, speed: aground ? 0 : speed, dock, mooredThrottle: 0 };
77	}
78	
79	/** The speed after one world step of throttle in [-AXIS_SCALE, AXIS_SCALE] (positive forward). */
80	export function nextSpeed(tuning: ShipTuning, speed: number, throttle: number): number {
81	  if (throttle > 0) {
82	    if (speed < 0) return Math.min(speed + tuning.braking, 0);
83	    const target = divTrunc(tuning.maxSpeed * throttle, AXIS_SCALE);
84	    return speed < target ? Math.min(speed + tuning.acceleration, target) : Math.max(speed - tuning.drag, target);
85	  }
86	  if (throttle < 0) {
87	    // Down brakes a ship under way, and reverses slowly from a stop.
88	    if (speed > 0) return Math.max(speed - tuning.braking, 0);
89	    const target = -divTrunc(tuning.maxReverseSpeed * -throttle, AXIS_SCALE);
90	    return speed > target ? Math.max(speed - tuning.reverseAcceleration, target) : Math.min(speed + tuning.drag, target);
91	  }
92	  return speed > 0 ? Math.max(speed - tuning.drag, 0) : Math.min(speed + tuning.drag, 0);
93	}
94	
95	/**
96	 * The nearest dock the ship at a position can moor at, or undefined: one whose tile the hull is on or beside, or whose
97	 * centre is within the dock radius with a clear straight run for the hull. Beside means any tile the hull overlaps is
98	 * one of the berth tile's eight neighbours; a diagonal one counts only if one of the two tiles it shares with the
99	 * berth is navigable, so a ship cannot moor through a pinch of land or shoal. Mooring moves the ship to the berth
100	 * centre, so without these checks it could cut through land that sailing would have stopped it at.
101	 */
102	export function dockInReach(config: SimulationConfig, x: number, y: number): Dock | undefined {
103	  const reach = config.ship.dockRadius * config.ship.dockRadius;
104	  let best: Dock | undefined;
105	  let bestDistance = Number.POSITIVE_INFINITY;
106	  for (const dock of config.map.docks) {
107	    const centre = tileCentre(config, dock.tileX, dock.tileY);
108	    const distance = (centre.x - x) * (centre.x - x) + (centre.y - y) * (centre.y - y);
109	    if (distance >= bestDistance) continue;
110	    if (hullIsBesideBerth(config, dock, x, y) || (distance <= reach && hullPathIsClear(config, x, y, centre.x, centre.y))) {
111	      best = dock;
112	      bestDistance = distance;
113	    }
114	  }
115	  return best;
116	}
117	
118	/** Whether a tile the hull at (x, y) overlaps is the dock's tile or an unpinched neighbour of it (see `dockInReach`). */
119	function hullIsBesideBerth(config: SimulationConfig, dock: Dock, x: number, y: number): boolean {
120	  const size = config.map.subUnitsPerTile;
121	  const half = config.ship.hullHalfSize;
122	  for (let row = Math.floor((y - half) / size); row <= Math.floor((y + half) / size); row++) {
123	    for (let column = Math.floor((x - half) / size); column <= Math.floor((x + half) / size); column++) {
124	      const dx = column - dock.tileX;
125	      const dy = row - dock.tileY;
126	      if (Math.abs(dx) > 1 || Math.abs(dy) > 1) continue;
127	      if (dx === 0 || dy === 0) return true;
128	      if (isNavigable(config.map, dock.tileX + dx, dock.tileY) || isNavigable(config.map, dock.tileX, dock.tileY + dy)) return true;
129	    }
130	  }
131	  return false;
132	}
133	
134	/**
135	 * The hull is a square of `hullHalfSize` around the position. It never overlaps a blocked tile, so a move only needs
136	 * to check the tile columns (or rows) its leading edge enters, in order: the first blocked one stops the hull flush
137	 * against it. However fast the ship, it cannot pass through a tile, so it never tunnels.
138	 */
139	function sweepX(config: SimulationConfig, x: number, y: number, dx: number): number {
140	  if (dx === 0) return x;
141	  const size = config.map.subUnitsPerTile;
142	  const half = config.ship.hullHalfSize;
143	  const top = Math.floor((y - half) / size);
144	  const bottom = Math.floor((y + half) / size);
145	  const blocked = (column: number) => {
146	    for (let row = top; row <= bottom; row++) if (!isNavigable(config.map, column, row)) return true;
147	    return false;
148	  };
149	  if (dx > 0) {
150	    const last = Math.floor((x + half + dx) / size);
151	    for (let column = Math.floor((x + half) / size) + 1; column <= last; column++) {
152	      if (blocked(column)) return column * size - 1 - half;
153	    }
154	  } else {
155	    const last = Math.floor((x - half + dx) / size);
156	    for (let column = Math.floor((x - half) / size) - 1; column >= last; column--) {
157	      if (blocked(column)) return (column + 1) * size + half;
158	    }
159	  }
160	  return x + dx;
161	}
162	
163	function sweepY(config: SimulationConfig, x: number, y: number, dy: number): number {
164	  if (dy === 0) return y;
165	  const size = config.map.subUnitsPerTile;
166	  const half = config.ship.hullHalfSize;
167	  const left = Math.floor((x - half) / size);
168	  const right = Math.floor((x + half) / size);
169	  const blocked = (row: number) => {
170	    for (let column = left; column <= right; column++) if (!isNavigable(config.map, column, row)) return true;
171	    return false;
172	  };
173	  if (dy > 0) {
174	    const last = Math.floor((y + half + dy) / size);
175	    for (let row = Math.floor((y + half) / size) + 1; row <= last; row++) {
176	      if (blocked(row)) return row * size - 1 - half;
177	    }
178	  } else {
179	    const last = Math.floor((y - half + dy) / size);
180	    for (let row = Math.floor((y - half) / size) - 1; row >= last; row--) {
181	      if (blocked(row)) return (row + 1) * size + half;
182	    }
183	  }
184	  return y + dy;
185	}
