189	 * sub-unit apart along the longer axis, so between two checks the hull moves at most one sub-unit on either axis and
190	 * no tile corner can slip between them.
191	 */
192	export function hullPathIsClear(config: SimulationConfig, fromX: number, fromY: number, toX: number, toY: number): boolean {
193	  const dx = toX - fromX;
194	  const dy = toY - fromY;
195	  const steps = Math.max(Math.abs(dx), Math.abs(dy));
196	  if (steps === 0) return hullIsClear(config, fromX, fromY);
197	  for (let index = 0; index <= steps; index++) {
198	    if (!hullIsClear(config, fromX + divTrunc(dx * index, steps), fromY + divTrunc(dy * index, steps))) return false;
199	  }
200	  return true;
201	}
