206	  const half = config.ship.hullHalfSize;
207	  for (let row = Math.floor((y - half) / size); row <= Math.floor((y + half) / size); row++) {
208	    for (let column = Math.floor((x - half) / size); column <= Math.floor((x + half) / size); column++) {
209	      if (!isNavigable(config.map, column, row)) return false;
210	    }
